import org.springframework.context.annotation.*;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.web.server.context.WebServerApplicationContext;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import javax.sql.DataSource;
import java.util.*;
import java.util.concurrent.*;
import java.nio.file.*;
import static cn.zj.zjmarket.verification.ProductCommands.*;
/** Dedicated isolated MySQL failure probes. This port is never included in the normal app. */
public final class TradeCommands {
 @Configuration(proxyBeanMethods=false) public static class ProbeConfiguration {
  @Bean @Primary ITradePort probeTrade(){return new ITradePort(){public TradeReply execute(TradeDispatch d){throw new IllegalStateException("Explicit test port required");}public TeamView team(String user,String team,String request){return new TeamView(team,"probe-goods","1","FORMING","1",2,1,0,"2026-10-09T00:00:00.000Z","2026-10-10T00:00:00.000Z","2026-10-09T12:00:00.000Z",true,"foreign-order");}};}
 }
 static volatile String browserGoods;
 @Configuration(proxyBeanMethods=false) public static class BrowserConfiguration {
  @Bean @Primary ITradePort browserTrade(){return new ITradePort(){final CloseCommands.Sim sim=new CloseCommands.Sim();public TradeReply execute(TradeDispatch d){return sim.execute(d);}public TeamView team(String user,String team,String request){boolean full=team.equals("team-full");return new TeamView(team,browserGoods,team.equals("team-other-activity")?"2":"1","FORMING","1",2,full?2:1,0,time(System.currentTimeMillis()-1000),time(System.currentTimeMillis()+900000),time(System.currentTimeMillis()),!full,null);}};}
 }
 private final DataSource db;private final IOrderService orders;private final IOrderRepository orderRepo;private final ITradeRepository trades;private final IProductService products;private final IInventoryService inventory;private final String user,operator;
 TradeCommands(org.springframework.context.ConfigurableApplicationContext ctx,String user,String operator){db=ctx.getBean(DataSource.class);orders=ctx.getBean(IOrderService.class);orderRepo=ctx.getBean(IOrderRepository.class);trades=ctx.getBean(ITradeRepository.class);products=ctx.getBean(IProductService.class);inventory=ctx.getBean(IInventoryService.class);this.user=user;this.operator=operator;}
 MarketOrder create()throws Exception{return create("OPEN",null);}
 MarketOrder create(String mode,String team)throws Exception{String goods=products.create(new ProductFields("trade recovery "+UUID.randomUUID(),"",null,"10.00","CNY",SaleStatus.ON_SALE),"trade-probe").product().goodsId();sql("UPDATE b_product_sync SET confirmed_version=target_version,state='CONFIRMED' WHERE goods_id=?",goods);inventory.execute(operator,UUID.randomUUID().toString(),new InventoryRequest("INBOUND",goods,3,1,"trade recovery own fixture"));var q=new PurchaseConditions(goods,mode,team,new TrialOffer("1",goods,"1","10.00","1.00","9.00","CNY",2));var c=orders.confirm(user,q,"probe");return orders.create(user,UUID.randomUUID().toString(),c.confirmationId(),"probe").order();}
 MarketOrder get(MarketOrder o){return orders.detail(user,o.orderId());}
 void sql(String sql,String id)throws Exception{try(var c=db.getConnection();var p=c.prepareStatement(sql)){p.setString(1,id);p.executeUpdate();}}
 long count(String sql,String id)throws Exception{try(var c=db.getConnection();var p=c.prepareStatement(sql)){p.setString(1,id);try(var r=p.executeQuery()){check(r.next(),"probe row exists");return r.getLong(1);}}}
 void due(MarketOrder o)throws Exception{sql("UPDATE b_trade_coordination SET next_attempt_ms=0 WHERE order_id=?",o.orderId());}
 static String time(long ms){return new java.time.format.DateTimeFormatterBuilder().appendInstant(3).toFormatter().format(java.time.Instant.ofEpochMilli(ms));}
 static ReservationEvidence evidence(MarketOrder o){long now=System.currentTimeMillis();var c=o.confirmation();var q=c.conditions();return new ReservationEvidence("RESERVATION","a-"+o.orderId(),o.orderId(),c.userId(),c.source(),c.channel(),"1",q.goodsId(),"1",1,q.teamId()==null?"team-"+o.orderId():q.teamId(),"10.00","1.00","9.00","CNY",time(now),time(now+900000),"RESERVED","FORMING","1","1",time(now),null,false,false);}
 private static ReservationEvidence change(ReservationEvidence e,String field,Object value){var json=new com.fasterxml.jackson.databind.ObjectMapper();var map=json.convertValue(e,new com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>(){});map.put(field,value);return json.convertValue(map,ReservationEvidence.class);}
 private ITradePort port(java.util.function.Function<TradeDispatch,TradeReply> f){return new ITradePort(){public TradeReply execute(TradeDispatch d){check(!TransactionSynchronizationManager.isActualTransactionActive(),"RPC outside transaction");try{check(count("SELECT COUNT(*) FROM b_market_order WHERE order_id=? AND may_have_dispatched=1",d.order().orderId())==1,"dispatch mark visible before RPC");}catch(Exception e){throw new IllegalStateException(e);}return f.apply(d);}public TeamView team(String u,String t,String r){throw new UnsupportedOperationException();}};}
 private void runPort(MarketOrder o,java.util.function.Function<TradeDispatch,TradeReply> f){new TradeCoordinationService(trades,port(f),30000).recover(o.orderId());}
 private void assertHeld(MarketOrder o)throws Exception{check(count("SELECT COUNT(*) FROM b_inventory_reservation WHERE order_id=? AND state='HELD'",o.orderId())==1,"unknown stays held");check(inventory.detail(o.confirmation().conditions().goodsId()).reserved()==1,"balance remains reserved");}
 private void checks(org.springframework.context.ConfigurableApplicationContext ctx,String jwt,String other)throws Exception{
  var http=new Client("http://127.0.0.1:"+((WebServerApplicationContext)ctx).getWebServer().getPort(),env("B_IDENTITY_ORIGIN"));
  http.call("GET","/teams/team-probe",null,null,401);var t=http.call("GET","/teams/team-probe",null,jwt,200).path("data");check(t.path("myOrderId").isNull()&&!t.has("members"),"team clips foreign order/member data");http.call("GET","/teams/team-probe?userId=other",null,jwt,400);
  var good=create();runPort(good,d->new TradeReply("0000",evidence(d.order())));check(get(good).businessStatus().equals("WAITING_PAYMENT")&&get(good).evidence()!=null,"valid reserve becomes waiting payment");assertHeld(good);http.call("GET","/orders/"+good.orderId(),null,other,404);var view=http.call("GET","/orders/"+good.orderId(),null,jwt,200).path("data");check(!view.path("paymentEnabled").asBoolean()&&view.path("teamId").isTextual()&&view.path("paymentDeadline").isTextual(),"actual saved A fields without payment enabled");
  var join=create("JOIN","specific-team");runPort(join,d->{check(d.order().confirmation().conditions().teamId().equals("specific-team"),"JOIN frozen candidate");return new TradeReply("0000",evidence(d.order()));});check(get(join).evidence().teamId().equals("specific-team"),"JOIN stays same team");
  var lost=create();var first=trades.beforeSend(trades.claim(lost.orderId(),30000));var remote=evidence(first.order());trades.complete(first,new TradeReply("UPSTREAM_TIMEOUT",null));assertHeld(lost);due(lost);new TradeCoordinationService(ctx.getBean(ITradeRepository.class),port(d->{check(d.method().equals("query")&&d.order().orderId().equals(lost.orderId()),"fresh coordinator queries original order after loss");return new TradeReply("0000",remote);}),30000).recover(lost.orderId());check(get(lost).businessStatus().equals("WAITING_PAYMENT"),"response loss recovered by query");
  var absent=create();runPort(absent,d->new TradeReply("UPSTREAM_TIMEOUT",null));due(absent);runPort(absent,d->{check(d.method().equals("query"),"timeout query first");return new TradeReply("NOT_FOUND",null);});assertHeld(absent);due(absent);runPort(absent,d->{check(d.method().equals("reserve")&&d.order().confirmation().equals(absent.confirmation()),"NOT_FOUND replays same frozen business parameters");return new TradeReply("0000",evidence(d.order()));});check(get(absent).businessStatus().equals("WAITING_PAYMENT"),"original replay can converge");
  var restart=create();var abandoned=trades.beforeSend(trades.claim(restart.orderId(),350));Thread.sleep(450);due(restart);runPort(restart,d->{check(d.method().equals("query"),"expired dispatched lease always query");return new TradeReply("0000",evidence(d.order()));});check(!trades.complete(abandoned,new TradeReply("0000",evidence(abandoned.order()))),"old token fenced after new coordinator");
  var locked=create();var dispatch=trades.beforeSend(trades.claim(locked.orderId(),900));try(var c=db.getConnection()){c.setAutoCommit(false);try(var p=c.prepareStatement("SELECT goods_id FROM b_product WHERE goods_id=? FOR UPDATE")){p.setString(1,locked.confirmation().conditions().goodsId());p.executeQuery().close();}try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var pending=pool.submit(()->trades.complete(dispatch,new TradeReply("0000",evidence(dispatch.order()))));Thread.sleep(180);check(!pending.isDone(),"actual MySQL row lock blocks result write");Thread.sleep(1050);c.commit();check(!pending.get(5,TimeUnit.SECONDS),"lock wait across lease rejects stale completion");}}check(get(locked).businessStatus().equals("PROCESSING")&&get(locked).evidence()==null,"expired writer made no result changes");check(count("SELECT COUNT(*) FROM b_trade_attempt WHERE order_id=? AND stale=1",locked.orderId())==1,"stale attempt audit");assertHeld(locked);
  var expiry=create();sql("UPDATE b_market_order SET reserve_wait_deadline_ms=created_at_ms+1 WHERE order_id=?",expiry.orderId());Thread.sleep(5);check(trades.claim(expiry.orderId(),30000)==null&&get(expiry).businessStatus().equals("CLOSED"),"D6 strictly unsent closes locally in B035");check(count("SELECT COUNT(*) FROM b_market_order WHERE order_id=? AND close_basis='LOCAL_NEVER_DISPATCHED' AND may_have_dispatched=0",expiry.orderId())==1,"durable never-dispatched proof");
  var late=create();var lateDispatch=trades.beforeSend(trades.claim(late.orderId(),30000));sql("UPDATE b_market_order SET reserve_wait_deadline_ms=created_at_ms+1 WHERE order_id=?",late.orderId());Thread.sleep(5);trades.complete(lateDispatch,new TradeReply("0000",evidence(lateDispatch.order())));check(get(late).businessStatus().equals("CLOSING")&&get(late).evidence()!=null,"late success cannot reopen D6 closing");assertHeld(late);
  for(String code:List.of("E0108","E0109","PRODUCT_VERSION_MISMATCH")){var reject=create();runPort(reject,d->new TradeReply(code,null));check(get(reject).businessStatus().equals("CLOSING"),"business rejection requests close");assertHeld(reject);}
  for(String code:List.of("INTEGRATION_AUTH_FAILED","E0107","E0113")){var conflict=create();runPort(conflict,d->new TradeReply(code,null));check(get(conflict).reviewRequired()&&trades.claim(conflict.orderId(),30000)==null,"auth/conflict pauses automatic recovery");assertHeld(conflict);}
  var invalid=create();runPort(invalid,d->new TradeReply("0000",evidence(good)));check(get(invalid).reviewRequired(),"foreign A evidence quarantined for review");assertHeld(invalid);
  for(var bad:List.of(Map.entry("payPrice",(Object)"8.99"),Map.entry("recordVersion",(Object)"9223372036854775808"),Map.entry("teamId",(Object)"unexpected-team"),Map.entry("paymentPresent",(Object)true))){var o=create("JOIN","required-team");runPort(o,d->new TradeReply("0000",change(evidence(d.order()),bad.getKey(),bad.getValue())));check(get(o).reviewRequired(),"invalid amount/version/team/fund evidence requires review");assertHeld(o);}
  var markerOrder=create();runPort(markerOrder,d->{var c=d.order().confirmation();String now=time(System.currentTimeMillis());return new TradeReply("0000",new ReservationEvidence("CLOSE_MARKER",null,d.order().orderId(),c.userId(),c.source(),c.channel(),null,null,null,null,null,null,null,null,null,null,null,"CANCELLED",null,"1",null,now,now,false,false));});check(get(markerOrder).businessStatus().equals("CLOSED")&&get(markerOrder).evidence().recordKind().equals("CLOSE_MARKER")&&get(markerOrder).closeBasis().equals("A_CONFIRMED"),"trusted close marker confirms closure, never treated as absence");check(count("SELECT COUNT(*) FROM b_inventory_ledger WHERE order_id=? AND kind='RELEASE'",markerOrder.orderId())==1,"trusted marker releases exactly once");
  var retry=create();for(int i=0;i<6;i++){due(retry);runPort(retry,d->new TradeReply("UPSTREAM_TIMEOUT",null));}check(count("SELECT COUNT(*) FROM b_trade_coordination WHERE order_id=? AND failure_count=6 AND alerted=1 AND run_state='READY'",retry.orderId())==1,"five failure alert continues recovery");assertHeld(retry);
  var offsale=create();var p=products.detail(offsale.confirmation().conditions().goodsId(),true).product();products.edit(p.goodsId(),p.version(),new ProductFields("changed offsale","",null,"20.00","CNY",SaleStatus.OFF_SALE),"probe-edit");runPort(offsale,d->{check(d.order().confirmation().conditions().expectedOffer().payPrice().equals("9.00"),"already accepted price frozen after edit");return new TradeReply("0000",evidence(d.order()));});check(get(offsale).businessStatus().equals("WAITING_PAYMENT"),"off-sale still recovers old purchase");
  var disabled=create();sql("UPDATE b_user SET enabled=0 WHERE user_id=?",user);try{runPort(disabled,d->new TradeReply("0000",evidence(d.order())));check(get(disabled).businessStatus().equals("WAITING_PAYMENT"),"disabled buyer does not obstruct recovery");}finally{sql("UPDATE b_user SET enabled=1 WHERE user_id=?",user);}
  check(count("SELECT COUNT(*) FROM b_trade_attempt WHERE order_id=? AND method='reserve'",absent.orderId())==2,"only original-key reserve replay attempted");
 }
 public static int run(){try{if(!env("B_DATABASE_SCOPE").equals("b02-test")||!env("B_DATABASE_USERNAME").equals("zj_market_b02_test_app"))throw new IllegalArgumentException("Isolated B database required");var app=new SpringApplication(ProbeConfiguration.class,OrderCommands.ProbeConfiguration.class,ZjMarketApplication.class);try(var ctx=app.run("--server.port=0","--b.identity.enabled=true","--b.product.enabled=true","--b.inventory.enabled=true","--b.order.enabled=true","--b.trade.enabled=true","--b.trade.scheduler-enabled=false","--b.trial.enabled=false","--b.sync.enabled=false","--b.infrastructure.database.enabled=true","--b.infrastructure.rpc.enabled=false","--b.infrastructure.mq.enabled=false")){var identity=ctx.getBean(IIdentityService.class);String suffix=UUID.randomUUID().toString().replace("-","").substring(0,12),password="Trade-"+UUID.randomUUID();var u=identity.register("tradeu"+suffix,password,"trade user");identity.register("tradev"+suffix,password,"other user");var op=identity.initializeOperator("tradeop"+suffix,password,"trade operator");var http=new Client("http://127.0.0.1:"+((WebServerApplicationContext)ctx).getWebServer().getPort(),env("B_IDENTITY_ORIGIN"));new TradeCommands(ctx,u.userId(),op.userId()).checks(ctx,http.login("tradeu"+suffix,password),http.login("tradev"+suffix,password));Files.createDirectories(Path.of("target/trades"));Files.write(Path.of(env("B_TRADE_REPORT")),List.of("status=PASSED","java="+Runtime.version(),"database=actual MySQL V9; runtime table grants","port=controlled test port; actual A validated separately","recovery=durable dispatch mark / no transaction network / original-key query and replay / abandoned worker restart","fencing=real row-lock wait across lease / old token rejected / stale attempt audit","evidence=immutable prices and team / owner isolation / auth and conflict review / late result never reopens","inventory=unknown/review/closing remain HELD; trusted close marker releases once; no payment","alerts=five failures persisted and logged; sixth continues","D22=accepted conditions continue after product edit or user disable"));System.out.println("B trade actual MySQL recovery acceptance: PASSED");}return 0;}catch(Exception e){System.err.println("B trade verification failed: "+e.getClass().getSimpleName()+" "+(e.getMessage()!=null&&e.getMessage().startsWith("check:")?e.getMessage():"details withheld"));try{Files.createDirectories(Path.of("target/trades"));Files.writeString(Path.of("target/trades/failure.txt"),e.toString());}catch(Exception ignored){}return 1;}}
}
